import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 19 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * earlier Practice Tests.
 */

// ─────────────────────── PRACTICE TEST 19 · R&W M1 (27) ──────────────────────
const T19_RW_M1: SatQuestion[] = [
  { id: "t19rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The cartographer's maps were prized for their ______ detail: every cove, sandbar, and tidal channel appeared exactly where a sailor would expect it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "careless", "vague", "decorative"], correct: 0, explanation: "Detail so exact that every feature is correctly placed is \"meticulous.\" \"Careless\" and \"vague\" describe the opposite, and \"decorative\" speaks to ornament, not accuracy." },
  { id: "t19rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of scientists ______ scheduled to release its findings at the conference next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "The subject is the singular collective noun \"committee,\" so the singular verb \"is\" is correct. The plural \"scientists\" is the object of \"of\" and does not control the verb, ruling out \"are\" and \"were.\"" },
  { id: "t19rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Coral polyps secrete calcium carbonate to build the reef around themselves; over centuries, the accumulated skeletons of countless generations form structures large enough to be seen from space.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Reefs are built gradually from the calcium carbonate skeletons of many generations of coral.", "Coral polyps avoid producing calcium carbonate.", "Reefs form within a single year.", "Coral skeletons dissolve before any reef can form."], correct: 0, explanation: "The text says polyps secrete calcium carbonate and that accumulated skeletons over centuries form the reef, which is choice A. B and D contradict the secretion and accumulation described, and C contradicts \"over centuries.\"" },
  { id: "t19rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail was washed out by the spring floods. ______, the rangers closed it until repairs could be completed.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "In contrast"], correct: 1, explanation: "The closure is a direct result of the washed-out trail, so the cause-and-effect transition \"Consequently\" fits. \"Nevertheless,\" \"However,\" and \"In contrast\" all signal contrast, which the relationship is not." },
  { id: "t19rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The expedition packed three essentials ______ a satellite phone, a first-aid kit, and extra fuel.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials, ", "essentials: ", "essentials; ", "essentials "], correct: 1, explanation: "A colon correctly introduces the list that specifies the \"three essentials.\" A comma is too weak to set off a list explained this way, a semicolon must join independent clauses, and no punctuation leaves the list run-on." },
  { id: "t19rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her lab notebook was unusually ______, with each measurement dated, labeled, and cross-referenced to the raw data.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["systematic", "haphazard", "brief", "illegible"], correct: 0, explanation: "Dating, labeling, and cross-referencing every entry shows an orderly method, which is \"systematic.\" \"Haphazard\" and \"illegible\" mean the opposite, and \"brief\" is unsupported by the thorough records described." },
  { id: "t19rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to artists who have completed at least one published book and who reside within the state; applicants who fail either requirement are not considered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An out-of-state author with a published book would not qualify.", "Every applicant automatically qualifies.", "The fellowship is open to unpublished writers anywhere.", "Residency alone guarantees the award."], correct: 0, explanation: "Both residency and a published book are required, so failing residency disqualifies the out-of-state author in choice A. B and D ignore the dual requirement, and C contradicts the publication requirement." },
  { id: "t19rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum digitized its entire photo archive. ______, it launched a public website where anyone could browse the collection.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "Launching the website is a further step added to the digitizing, so \"In addition\" fits. \"However\" and \"Instead\" signal contrast or replacement, and \"Otherwise\" implies an alternative consequence." },
  { id: "t19rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the chef's tasting menu ______, noting that each course built on the last toward a single, coherent theme.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "disjointed", "bland", "wasteful"], correct: 0, explanation: "Courses building toward one coherent theme describe a \"cohesive\" menu. \"Disjointed\" is the opposite, and \"bland\" and \"wasteful\" address flavor and excess rather than coherence." },
  { id: "t19rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Desert kangaroo rats can survive without ever drinking water, instead producing the moisture they need by metabolizing the dry seeds they eat.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Kangaroo rats meet their water needs by metabolizing the seeds they eat.", "Kangaroo rats drink large amounts of water daily.", "Kangaroo rats cannot survive in deserts.", "Kangaroo rats eat only moist foods."], correct: 0, explanation: "The text states they produce needed moisture by metabolizing dry seeds, which is choice A. B and D contradict \"without ever drinking water\" and \"dry seeds,\" and C contradicts their survival in the desert." },
  { id: "t19rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither of the two proposals ______ ready for a vote at today's meeting.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "\"Neither\" is singular and takes the singular verb \"is.\" The plural \"proposals\" is the object of \"of\" and does not govern the verb, eliminating \"are,\" \"were,\" and \"have been.\"" },
  { id: "t19rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first edition of the dictionary sold poorly. ______, it later became a collector's item prized by linguists.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "Poor sales followed by later prestige is a contrast, signaled by \"Still.\" \"Therefore\" implies cause and effect, \"For instance\" introduces an example, and \"In short\" summarizes." },
  { id: "t19rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study reported recall accuracy of 88% among participants who slept eight hours, 74% among those who slept six hours, and 59% among those who slept four hours.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Recall accuracy decreased as sleep duration decreased.", "Recall accuracy was highest among those who slept four hours.", "Sleep had no effect on recall accuracy.", "All three groups recalled equally well."], correct: 0, explanation: "Accuracy falls from 88% to 74% to 59% as sleep drops from eight to six to four hours, so accuracy decreased with less sleep (choice A). B reverses the trend, and C and D ignore the clear differences." },
  { id: "t19rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive contains a manuscript ______ had been thought lost since the eighteenth century.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The relative pronoun \"that\" correctly introduces the clause modifying \"manuscript.\" \"What\" cannot follow a noun this way, \"where\" marks a place, and \"and it\" creates a comma splice without the needed clause structure." },
  { id: "t19rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Stepping off the train, ______ the unfamiliar skyline left the traveler momentarily disoriented.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["stepping off the train, the unfamiliar skyline left the traveler disoriented", "the traveler stepped off the train and felt disoriented by the unfamiliar skyline", "the unfamiliar skyline, stepping off the train, disoriented the traveler", "disoriented, the unfamiliar skyline confused the traveler off the train"], correct: 1, explanation: "The modifier \"stepping off the train\" must describe the person doing the stepping, and only choice B places \"the traveler\" right after it. The other choices illogically attach the action to \"the skyline.\"" },
  { id: "t19rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist argues that remote work, though it lengthens some projects, boosts overall productivity because employees lose less time to commuting and interruptions.", prompt: "Which finding, if true, would most strengthen the economist's claim?", type: "mcq", choices: ["Firms that adopted remote work completed more total output per worker than comparable in-office firms.", "Remote employees spend more time in scheduled meetings.", "Most workers say they prefer working from home.", "Commutes are shorter on weekends than on weekdays."], correct: 0, explanation: "Higher total output per remote worker directly supports the claim of boosted productivity (choice A). Preference (C) and commute timing (D) do not measure productivity, and more meetings (B) would, if anything, undercut the claim." },
  { id: "t19rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with her camera operators, ______ filming the final scene at dawn tomorrow.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The subject is the singular \"director\"; the \"together with\" phrase does not change the verb's number, so \"is\" is correct. The plural-sounding \"operators\" inside that phrase does not govern the verb." },
  { id: "t19rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to underscore that two independent teams reached the same surprising result. ______, both groups measured the comet's tail at nearly the same length.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "\"Remarkably\" highlights the striking agreement between the two teams, matching the goal of underscoring a surprising shared result. The contrast words \"By contrast\" and \"However\" wrongly imply disagreement." },
  { id: "t19rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The novel's ending is intentionally ______: readers close the book unsure whether the protagonist has triumphed or merely deceived herself.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "explicit", "predictable", "cheerful"], correct: 0, explanation: "Leaving readers unsure of the outcome makes the ending \"ambiguous.\" \"Explicit\" and \"predictable\" describe clarity or certainty, the opposite of the uncertainty described, and \"cheerful\" addresses tone, not interpretive openness." },
  { id: "t19rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate applies only to vehicles purchased new after January and registered to a household within the city limits; used or out-of-city purchases do not qualify.", prompt: "Which vehicle clearly qualifies for the rebate?", type: "mcq", choices: ["A new car bought in March and registered to a household inside the city.", "A used car bought in March within the city.", "A new car bought in March and registered outside the city.", "A car bought before January."], correct: 0, explanation: "Both conditions — new and after January, plus registered inside the city — are met only in choice A. B fails the \"new\" rule, C fails the city-registration rule, and D fails the timing rule." },
  { id: "t19rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the lighthouse lens ______ they repainted the weathered iron railing.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["lens, and then", "lens and, then", "lens then", "lens, then"], correct: 0, explanation: "Two independent clauses must be joined by a comma plus a coordinating conjunction, which choice A supplies with \"and then.\" The other choices either misplace the comma or omit the conjunction, creating run-ons or comma splices." },
  { id: "t19rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although he was famous for his ______ negotiating style, the executive could be remarkably patient when mentoring younger colleagues.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["aggressive", "gentle", "timid", "indifferent"], correct: 0, explanation: "The contrast signaled by \"Although\" and \"remarkably patient\" implies his usual style was the opposite — \"aggressive.\" \"Gentle\" and \"timid\" would not contrast with patience, and \"indifferent\" does not fit a negotiating style." },
  { id: "t19rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A geographer notes that coastal cities with deep natural harbors grew into trade hubs faster than those with shallow ports, crediting the ease of docking large ships.", prompt: "Which choice best describes the geographer's explanation?", type: "mcq", choices: ["Deep harbors let large ships dock easily, accelerating a city's growth as a trade hub.", "Shallow ports attracted more shipping than deep harbors.", "Harbor depth had no effect on trade.", "Large ships avoided deep harbors."], correct: 0, explanation: "The geographer credits the ease of docking large ships in deep harbors for faster growth, which is choice A. B and D reverse the stated relationship, and C denies the effect the text asserts." },
  { id: "t19rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The council delayed the vote ______ it still lacked the engineering report it had requested.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "When a \"because\" clause follows the main clause and is essential to its meaning, no punctuation is needed before it, as in choice A. A semicolon and a colon both require different structures, and the comma is unnecessary here." },
  { id: "t19rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new irrigation system cut the farm's water use by a third. ______, it lowered the farm's annual costs substantially.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "Lower costs follow logically from reduced water use, a cause-and-effect link signaled by \"As a result.\" The contrast words and \"For example\" do not capture this consequence." },
  { id: "t19rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The instructor gave ______ feedback, pointing to the exact lines a student could revise rather than offering vague encouragement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "abstract", "evasive", "irrelevant"], correct: 0, explanation: "Pointing to exact lines rather than offering vague comments describes \"specific\" feedback. \"Abstract\" and \"evasive\" suggest the vagueness the sentence rejects, and \"irrelevant\" is unsupported." },
  { id: "t19rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study found that reintroducing beavers to a degraded watershed slowed runoff, which raised the water table, which in turn allowed drought-stressed meadows to green again.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Returning beavers set off a chain of effects that helped degraded meadows recover.", "Beavers directly planted the meadow grasses.", "The water table fell after the beavers returned.", "Meadows withered once the beavers arrived."], correct: 0, explanation: "Beavers slowed runoff, which raised the water table, which let meadows recover — a chain of effects (choice A). C and D contradict the rising water table and greening described, and B misstates the indirect mechanism." },
];

// ─────────────────────── PRACTICE TEST 19 · R&W M2 easy (27) ─────────────────
const T19_RW_M2E: SatQuestion[] = [
  { id: "t19rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was too ______ to carry, so we took some books out of it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "empty", "green", "quiet"], correct: 0, explanation: "Taking books out to make it easier to carry means the backpack was \"heavy.\" The other words do not explain why someone would remove the books." },
  { id: "t19rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The two puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Two puppies\" is plural, so the plural verb \"are\" is correct. \"Is,\" \"was,\" and \"am\" are singular or first-person forms that do not agree." },
  { id: "t19rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; many use echoes from their own calls to find insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats use echoes to locate insects at night.", "Bats cannot find food in the dark.", "Bats are completely blind.", "Bats hunt only during the day."], correct: 0, explanation: "The text says bats use echoes to find insects in the dark, which is choice A. B, C, and D each contradict a detail in the sentence." },
  { id: "t19rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It began to rain hard. ______, we moved the picnic inside.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "Moving inside is the result of the rain, so the cause-and-effect word \"So\" fits. \"However\" signals contrast and the others do not match the cause." },
  { id: "t19rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at our grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "\"Last night\" signals the past, so the past-tense verb \"ate\" is correct. The other forms are present tense or incomplete." },
  { id: "t19rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was ______, so it took us all afternoon to finish.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["difficult", "simple", "tiny", "warm"], correct: 0, explanation: "Taking all afternoon suggests the puzzle was \"difficult.\" \"Simple\" would mean the opposite, and \"tiny\" and \"warm\" do not relate to how long it took." },
  { id: "t19rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, reduces traffic, and gives students daily exercise.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is harmful.", "Walking to school only saves money.", "Driving to school is always better."], correct: 0, explanation: "Three benefits are listed, so choice A captures the main idea. B and D contradict the positive tone, and C ignores two of the three benefits." },
  { id: "t19rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to the parade.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Orange\" begins with a vowel sound, so \"an\" is correct. \"A\" is used before consonant sounds, and \"the only\" and \"some\" change the meaning." },
  { id: "t19rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lake was so ______ that we could see the pebbles at the bottom.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "muddy", "loud", "frozen"], correct: 0, explanation: "Being able to see the bottom means the water was \"clear.\" \"Muddy\" and \"frozen\" would hide the pebbles, and \"loud\" does not describe water this way." },
  { id: "t19rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My cousin and I ______ planning a trip to the mountains.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The compound subject \"my cousin and I\" is plural, so \"are\" is correct. The singular and first-person forms do not agree with a plural subject." },
  { id: "t19rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Earthworms loosen soil as they tunnel, which lets air and water reach plant roots more easily.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Earthworms help soil by loosening it as they tunnel.", "Earthworms pack soil tightly.", "Earthworms keep water away from roots.", "Earthworms harm plant roots."], correct: 0, explanation: "The text says tunneling loosens soil and helps air and water reach roots, which is choice A. B, C, and D each contradict that benefit." },
  { id: "t19rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, the whole street went dark.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The dark street is the result of the power outage, so \"As a result\" fits. \"However\" and \"Instead\" signal contrast, which does not match." },
  { id: "t19rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the choir ______ a new song for the spring concert.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["learn", "learns", "learned", "learning"], correct: 2, explanation: "\"Yesterday\" requires the past tense \"learned.\" The other options are present tense or incomplete." },
  { id: "t19rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After studying for hours, the student felt ______ and went straight to bed.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "Going straight to bed after long studying suggests the student felt \"tired.\" The other choices do not explain heading to bed." },
  { id: "t19rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from noon to eight in the evening on weekdays but stays closed on Mondays.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot swim at the pool on Mondays.", "The pool opens at dawn.", "The pool is open every day.", "The pool closes at noon."], correct: 0, explanation: "The pool is closed on Mondays, so choice A is supported. B, C, and D each conflict with the stated hours." },
  { id: "t19rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat curled up in ______ favorite spot by the window.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The singular possessive \"its\" matches the singular noun \"cat.\" \"It's\" means \"it is,\" and \"their\" and \"they're\" are plural forms." },
  { id: "t19rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through the winter. ______, bears hibernate for months in their dens.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Bears are an example of an animal that sleeps through winter, so \"For example\" fits. The other words signal contrast or alternatives." },
  { id: "t19rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The soup needed more flavor, so the cook added a ______ of salt.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["pinch", "gallon", "color", "shadow"], correct: 0, explanation: "A small amount of salt is a \"pinch.\" A \"gallon\" is far too much, and \"color\" and \"shadow\" are not amounts of salt." },
  { id: "t19rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The shelves ______ filled with books of every size.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Shelves\" is plural, so the plural verb \"are\" is correct. The singular and first-person forms do not agree." },
  { id: "t19rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Salt was once so valuable that it was used as money in some ancient societies.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Salt was highly valued and even used as money in the past.", "Salt has never had any value.", "Salt cannot be traded.", "Salt was useless to ancient people."], correct: 0, explanation: "The text says salt was so valuable it served as money, which is choice A. B, C, and D all contradict that value." },
  { id: "t19rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to hike the long trail. ______, a sudden storm forced us to turn back.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "Planning to hike but being forced back is a contrast, signaled by \"However.\" \"Therefore\" and \"Similarly\" do not fit, and \"For example\" introduces an example." },
  { id: "t19rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month our class ______ to visit the science center.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The singular noun \"class\" takes \"plans,\" and \"next month\" fits the present-as-future use. \"Plan\" is plural, \"planned\" is past, and \"planning\" is incomplete." },
  { id: "t19rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new tablet is very ______; it can run all day on a single charge.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["efficient", "wasteful", "broken", "noisy"], correct: 0, explanation: "Running all day on one charge means the tablet is \"efficient.\" \"Wasteful\" and \"broken\" mean the opposite, and \"noisy\" is unrelated to battery life." },
  { id: "t19rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Planting trees in a city can provide shade, clean the air, and give birds a place to nest.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Planting city trees offers several benefits.", "City trees serve no purpose.", "Trees harm city air.", "Trees only provide shade."], correct: 0, explanation: "Three benefits are listed, so choice A is the main idea. B and C contradict the positive points, and C ignores two of the three." },
  { id: "t19rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He ordered ______ apple from the snack cart.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Apple\" begins with a vowel sound, so \"an\" is correct. \"A\" precedes consonant sounds, and \"the only\" and \"some\" change the meaning." },
  { id: "t19rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were clear and short. ______, the recipe used only five ingredients.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "A second easy feature is added, so \"In addition\" fits. The other words signal contrast or alternatives." },
  { id: "t19rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "A surprising magic trick leaves an audience \"amazed.\" \"Bored\" and \"sleepy\" suggest the opposite, and \"angry\" does not fit a successful trick." },
];

// ─────────────────────── PRACTICE TEST 19 · R&W M2 hard (27) ─────────────────
const T19_RW_M2H: SatQuestion[] = [
  { id: "t19rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The official's statement was so ______ that supporters and critics alike claimed it endorsed their position.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "candid", "blunt", "decisive"], correct: 0, explanation: "A statement vague enough for opposing sides to claim is \"equivocal\" (deliberately ambiguous). \"Candid,\" \"blunt,\" and \"decisive\" all imply clarity, which would not let both sides claim it." },
  { id: "t19rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The lecture spends most of its time recounting a single failed expedition before, in its closing minutes, distilling from that story a general lesson about risk.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from a detailed example to a broader generalization.", "It opens with a thesis it never supports.", "It lists unrelated definitions.", "It repeats one statistic throughout."], correct: 0, explanation: "A detailed story followed by a general lesson is a move from specific to general (choice A). B, C, and D describe structures the passage does not use." },
  { id: "t19rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A reservoir was at 95% capacity in spring, 90% by midsummer, and 62% by early autumn.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The reservoir's level dropped more sharply in late summer than in early summer.", "The reservoir filled steadily through the year.", "The level stayed constant all year.", "The reservoir was empty by midsummer."], correct: 0, explanation: "A 5-point drop early (95 to 90) versus a 28-point drop later (90 to 62) shows a sharper late-summer decline (choice A). B and C contradict the falling figures, and D contradicts the 90% midsummer reading." },
  { id: "t19rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The plan would shorten the harvest season dramatically. ______, it would require machinery too costly for small farms to afford.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "A clear benefit followed by a serious drawback is a contrast, signaled by \"However.\" \"Therefore,\" \"Likewise,\" and \"Accordingly\" all imply agreement or consequence rather than tension." },
  { id: "t19rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The program teaches interns to draft reports, to lead meetings, and ______ data clearly.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure with \"to draft\" and \"to lead\" requires the infinitive \"to present.\" The gerund and bare or past forms break the parallelism." },
  { id: "t19rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its author's youth, recounting his cruelties as frankly as his kindnesses.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "record", "recall"], correct: 0, explanation: "Recounting cruelties as frankly as kindnesses means the memoir refuses to \"romanticize\" the author's youth. \"Condemn\" is the opposite extreme, and \"record\" and \"recall\" describe neutral acts the memoir clearly does perform." },
  { id: "t19rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats the famine as a purely natural disaster, the revised history casts it as the predictable outcome of misguided policy.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast a natural-disaster account of a famine with a policy-driven one.", "To prove the famine had no human causes.", "To summarize only the traditional account.", "To deny that the famine occurred."], correct: 0, explanation: "The \"Where … the … the revised …\" construction contrasts two explanations of the famine (choice A). B and D contradict the policy-driven view, and C ignores the second account." },
  { id: "t19rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The afternoon class mastered the material quickly ______ the morning class needed several extra sessions.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["quickly, the", "quickly; the", "quickly the", "quickly: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone creates a splice, no punctuation creates a run-on, and a colon requires the second part to explain the first." },
  { id: "t19rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the report is so guarded that its key recommendation must be inferred from a single buried footnote.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["forthright", "evasive", "guarded", "cautious"], correct: 0, explanation: "\"Far from\" signals the opposite of what follows; a report so guarded that its point is buried is the opposite of \"forthright\" (frank and open). \"Evasive,\" \"guarded,\" and \"cautious\" all match the guardedness rather than contrast with it." },
  { id: "t19rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Officials claimed the new bypass had eliminated downtown congestion. Yet in the months after it opened, average rush-hour speeds downtown actually fell.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that complicates the officials' claim.", "It restates the officials' claim word for word.", "It confirms congestion was eliminated.", "It proposes building a second bypass."], correct: 0, explanation: "Slower rush-hour speeds complicate the claim that congestion was eliminated (choice A). B and C misread the contradiction signaled by \"Yet,\" and D introduces a proposal the text does not make." },
  { id: "t19rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The grant rewarded three traits ______ originality, feasibility, and clear public benefit.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["traits,", "traits:", "traits;", "traits"], correct: 1, explanation: "A colon correctly introduces the list specifying the \"three traits.\" A comma is too weak, a semicolon must separate independent clauses, and no punctuation leaves the list unmarked." },
  { id: "t19rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced strong antibody levels in early trials. ______, it offered little protection against the newest variant.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "A strong early result followed by a notable shortfall is a concession, best signaled by \"Nonetheless.\" \"Indeed,\" \"Therefore,\" and \"Likewise\" imply agreement or consequence." },
  { id: "t19rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, soil treated with the additive retained 40% more moisture than untreated soil, but it also supported 15% fewer earthworms.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The additive raised moisture retention but lowered earthworm counts.", "The additive raised both moisture and earthworm counts.", "The additive had no measurable effect.", "Untreated soil retained more moisture."], correct: 0, explanation: "Treated soil held more moisture (+40%) but had fewer earthworms (−15%), exactly choice A. B and D contradict the reported figures, and C ignores both measured changes." },
  { id: "t19rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The statue that stands in the courtyard ______ to a sculptor whose later commissions made her famous.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The singular subject \"statue\" (not the plural \"commissions\" inside the modifier) takes the singular verb \"belongs.\" \"Belong\" is plural, and \"belonging\" and \"to belong\" are nonfinite." },
  { id: "t19rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was known for her ______ — for cutting any sentence that did not earn its place on the page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigor", "leniency", "indecision", "nostalgia"], correct: 0, explanation: "Cutting every sentence that fails to earn its place shows demanding strictness, which is \"rigor.\" \"Leniency\" is the opposite, and \"indecision\" and \"nostalgia\" do not describe disciplined editing." },
  { id: "t19rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by conceding that early electric cars were slow and short-ranged, then argues that those very weaknesses pushed engineers to invent the batteries that now make the cars practical.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an early weakness as the source of a later strength.", "It denies that early electric cars had any flaws.", "It claims electric cars never improved.", "It lists car prices across decades."], correct: 0, explanation: "The early weaknesses are reframed as the spur for the batteries that made the cars practical (choice A). B and C contradict the concession and the improvement described, and D names content the passage lacks." },
  { id: "t19rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed for weeks in a small studio ______ the vast concert hall felt intimidating to the young pianist.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the vast concert hall felt intimidating to the young pianist", "the young pianist found the vast concert hall intimidating", "intimidating was the vast concert hall", "it felt intimidating, the vast hall"], correct: 1, explanation: "The modifier \"Having rehearsed for weeks\" must describe the person who rehearsed, and only choice B places \"the young pianist\" right after it. The others illogically make \"the concert hall\" the one who rehearsed." },
  { id: "t19rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The compound killed the bacteria in a test tube. ______, it proved harmless to bacteria living inside infected tissue.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In living tissue, however", "For this reason", "Similarly"], correct: 1, explanation: "The contrast between test-tube success and failure inside tissue is best signaled by \"In living tissue, however.\" \"Consequently,\" \"For this reason,\" and \"Similarly\" all imply agreement rather than the reversal described." },
  { id: "t19rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, observing how a brief opening motif returns, reshaped, in every movement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["integrated", "fragmented", "arbitrary", "monotonous"], correct: 0, explanation: "A motif returning, reshaped, across every movement gives the work an \"integrated\" design. \"Fragmented\" and \"arbitrary\" suggest disorder, and \"monotonous\" implies dull sameness rather than purposeful unity." },
  { id: "t19rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six schools, those that added a daily reading period saw test scores climb by an average of 12%, while those that kept their schedules unchanged saw no improvement.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding a daily reading period was associated with higher test scores.", "Keeping schedules unchanged raised scores.", "Reading periods had no relationship to scores.", "All six schools changed their schedules."], correct: 0, explanation: "Schools that added reading time saw a 12% rise while others saw none, supporting choice A. B and C contradict the data, and D contradicts the schools that kept schedules unchanged." },
  { id: "t19rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The architect's early sketches — rough, hurried, and barely legible ______ already revealed the bold curves of her later towers.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sketches —", "sketches,", "sketches", "sketches;"], correct: 0, explanation: "A pair of dashes sets off the interrupting description, and the second dash must close it. A comma or semicolon cannot pair with the opening dash, and omitting punctuation leaves the interruption unclosed." },
  { id: "t19rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the analyst's forecast as ______, only to see the downturn she predicted arrive within the year.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["alarmist", "prescient", "accurate", "measured"], correct: 0, explanation: "Dismissing a forecast that then comes true means the board wrongly judged it \"alarmist\" (needlessly fearful). \"Prescient\" and \"accurate\" describe the forecast's correctness, which is the opposite of the board's dismissive view." },
  { id: "t19rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One historian blames the empire's collapse on overextended borders; another points to a collapse in tax revenue. A third contends that the two problems fed on each other.", prompt: "Which choice best describes the third historian's position?", type: "mcq", choices: ["The two proposed causes reinforced one another to bring on the collapse.", "Neither borders nor revenue mattered at all.", "Only overextended borders mattered.", "The empire never actually collapsed."], correct: 0, explanation: "The third historian says the two problems \"fed on each other,\" meaning they reinforced one another (choice A). B and D deny the causes or the collapse, and C names only one cause." },
  { id: "t19rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The engineers rebuilt the dam's spillway ______ the original had cracked under the record floodwaters.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["spillway, the", "spillway; the", "spillway the", "spillway: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone makes a splice, no punctuation makes a run-on, and a colon requires the second clause to explain or specify the first." },
  { id: "t19rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the boom's rewards were narrowly distributed. ______, downtown investors prospered while outlying neighborhoods saw little gain.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The second sentence gives a precise illustration of the narrow distribution, so \"Specifically\" fits. \"In contrast\" and \"Nevertheless\" signal opposition, and \"Otherwise\" implies an alternative outcome." },
  { id: "t19rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying up every loose thread, the screenwriter leaves the rivalry ______, inviting viewers to imagine how it might end.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "settled", "trivial", "concluded"], correct: 0, explanation: "Declining to tie up the threads leaves the rivalry \"unresolved.\" \"Settled\" and \"concluded\" mean the opposite, and \"trivial\" addresses importance rather than closure." },
  { id: "t19rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author acknowledges that her dataset covered only two seasons, but she argues that the pattern she observed was so pronounced and consistent that it warrants a multi-year study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She admits a limitation while defending the importance of her finding.", "She claims her data are beyond question.", "She abandons her finding entirely.", "She argues no further study is needed."], correct: 0, explanation: "She concedes the short two-season window yet defends the finding's significance, exactly choice A. B overstates her confidence, and C and D contradict her call for a multi-year study." },
];

// ─────────────────────── PRACTICE TEST 19 · MATH M1 (22) ─────────────────────
const T19_M_M1: SatQuestion[] = [
  { id: "t19m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Subtract 8 from both sides to get 5x = 35, then divide by 5 to get x = 7. Check: 5(7) + 8 = 35 + 8 = 43. A common trap is dividing before subtracting the 8." },
  { id: "t19m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of rice for every 6 servings. How many cups are needed for 15 servings?", type: "mcq", choices: ["5", "4", "6", "7"], correct: 0, explanation: "Goal: scale the ratio. Rice per serving is 2/6 = 1/3 cup. Multiply by 15 servings: (1/3)(15) = 5 cups. Check: 5 cups over 15 servings is 1/3 cup each, matching the recipe. The trap is multiplying 2 by 15 without dividing by 6." },
  { id: "t19m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 7, what is the value of f(2)?", type: "mcq", choices: ["5", "11", "1", "17"], correct: 0, explanation: "Goal: evaluate the function at x = 2. Substitute: f(2) = 3(2²) − 7 = 3(4) − 7 = 12 − 7 = 5. The trap is squaring after multiplying, giving (3·2)² = 36; order of operations requires squaring 2 first." },
  { id: "t19m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 16. What is its radius?", type: "grid", gridAnswers: ["8"], explanation: "Goal: find the radius. The radius is half the diameter, so r = 16/2 = 8. Check: doubling 8 gives the diameter of 16. The trap is doubling the diameter instead of halving it." },
  { id: "t19m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 5x − 3 passes through the point (2, k). What is the value of k?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the y-value when x = 2. Substitute x = 2: k = 5(2) − 3 = 10 − 3 = 7. Check: the point (2, 7) satisfies the equation. The trap is subtracting before multiplying, giving 5(2 − 3) = −5." },
  { id: "t19m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find the missing value. The mean equation is (6 + 10 + x)/3 = 9, so 16 + x = 27 and x = 11. Check: (6 + 10 + 11)/3 = 27/3 = 9. The trap is forgetting to multiply the mean by 3 to recover the total." },
  { id: "t19m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 5 = 26, what is the value of x?", type: "mcq", choices: ["7", "21", "9", "8"], correct: 0, explanation: "Goal: solve for x. Subtract 5 to get 3x = 21, then divide by 3 to get x = 7. Check: 3(7) + 5 = 21 + 5 = 26. The trap is forgetting to divide after subtracting, giving 21." },
  { id: "t19m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the sum of the roots. Factoring gives (x − 4)(x − 5) = 0, so the roots are 4 and 5 and their sum is 9. As a check, the sum of roots equals −b/a = 9/1 = 9. The trap is using the product (20) instead of the sum." },
  { id: "t19m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A book's price increased from $40 to $46. What was the percent increase?", type: "mcq", choices: ["15%", "6%", "12%", "20%"], correct: 0, explanation: "Goal: find percent increase. The increase is 46 − 40 = 6, and 6/40 = 0.15 = 15%. Check: 15% of 40 is 6, which added to 40 gives 46. The trap is using the new price 46 as the base instead of the original 40." },
  { id: "t19m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["70"], explanation: "Goal: find the third angle. The angles of a triangle sum to 180°, so the third is 180 − 45 − 65 = 70°. Check: 45 + 65 + 70 = 180. The trap is using 360° instead of 180° for a triangle." },
  { id: "t19m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the total cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model the cost. The fixed fee $40 is added once and the $30 rate multiplies the hours h, giving C = 30h + 40. Check: at h = 0 the cost is the $40 fee, as expected. The trap is swapping the rate and the fixed fee." },
  { id: "t19m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 2) = x² + bx − 10, what is the value of b?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find b. Expanding the left side gives x² + 3x − 10, so matching the middle term shows b = 3. Check: the outer and inner products are −2x and 5x, which sum to 3x. The trap is adding 5 and −2 incorrectly or missing a sign." },
  { id: "t19m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 150 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["60", "40", "90", "75"], correct: 0, explanation: "Goal: find a part of a whole. Compute 40% of 150 as 0.40 × 150 = 60. Check: 60 out of 150 is indeed 40%. The trap is treating 40 as the count rather than a percentage." },
  { id: "t19m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 3) = 2x + 9, what is the value of x?", type: "mcq", choices: ["8", "6", "4", "12"], correct: 0, explanation: "Goal: solve for x. Distribute to get 5x − 15 = 2x + 9, subtract 2x to get 3x − 15 = 9, then 3x = 24 and x = 8. Check: 5(8 − 3) = 25 and 2(8) + 9 = 25. The trap is forgetting to distribute the 5 to the −3." },
  { id: "t19m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(12 + 5) = 2(17) = 34. Check: the two lengths (24) plus the two widths (10) give 34. The trap is computing the area, 12 × 5 = 60, instead of the perimeter." },
  { id: "t19m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential equation. Write 27 as 3³, so 3^(x−1) = 3³ means x − 1 = 3 and x = 4. Check: 3^(4−1) = 3³ = 27. The trap is solving x − 1 = 27 or dividing 27 by 3." },
  { id: "t19m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "180", "90"], correct: 0, explanation: "Goal: convert map distance to real distance. Multiply 5 inches by 30 miles per inch: 5 × 30 = 150 miles. Check: 150 miles ÷ 30 miles per inch equals 5 inches. The trap is dividing instead of multiplying by the scale." },
  { id: "t19m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use rise over run: (15 − 3)/(6 − 2) = 12/4 = 3. Check: going from x = 2 to x = 6 (run 4) the y rises by 12, which is 3 per unit. The trap is reversing the order of the coordinates in numerator and denominator." },
  { id: "t19m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x + 5, what value of x makes f(x) = 29?", type: "mcq", choices: ["6", "8", "7", "5"], correct: 0, explanation: "Goal: solve f(x) = 29. Set 4x + 5 = 29, subtract 5 to get 4x = 24, then x = 6. Check: 4(6) + 5 = 24 + 5 = 29. The trap is dividing 29 by 4 before subtracting the 5." },
  { id: "t19m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 7. What is its area, in terms of π?", type: "mcq", choices: ["49π", "14π", "7π", "21π"], correct: 0, explanation: "Goal: find the area. Use A = πr² = π(7²) = 49π. Check: squaring the radius 7 gives 49. The trap is using the circumference formula 2πr = 14π instead of the area formula." },
  { id: "t19m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3 to get 4x − 3 = 17, add 3 to get 4x = 20, then x = 5. Check: 4(5) − 3 = 20 − 3 = 17. The trap is subtracting 3 instead of adding it when moving it across." },
  { id: "t19m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "grid", gridAnswers: ["660"], explanation: "Goal: find total pay. Multiply the rate by the hours: 22 × 30 = 660 dollars. Check: 22 × 30 is the same as 22 × 3 × 10 = 66 × 10 = 660. The trap is adding the two numbers instead of multiplying." },
];

// ─────────────────────── PRACTICE TEST 19 · MATH M2 easy (22) ────────────────
const T19_M_M2E: SatQuestion[] = [
  { id: "t19m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 21, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: solve for x. Subtract 9 from both sides to get x = 21 − 9 = 12. Check: 12 + 9 = 21. The trap is adding instead of subtracting." },
  { id: "t19m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 10% of 80?", type: "mcq", choices: ["8", "10", "18", "80"], correct: 0, explanation: "Goal: find a percentage. Compute 0.10 × 80 = 8. Check: 10% means one tenth, and one tenth of 80 is 8. The trap is shifting the decimal the wrong way to get 800." },
  { id: "t19m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the area. Multiply length by width: 9 × 4 = 36. Check: 9 × 4 is the same as 9 + 9 + 9 + 9 = 36. The trap is computing the perimeter, 2(9 + 4) = 26, instead." },
  { id: "t19m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 7x = 56, what is the value of x?", type: "mcq", choices: ["8", "7", "49", "63"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 7: x = 56 ÷ 7 = 8. Check: 7 × 8 = 56. The trap is subtracting 7 from 56 instead of dividing." },
  { id: "t19m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate the expression. First square: 5² = 25, then subtract: 25 − 4 = 21. Check: order of operations puts the exponent before the subtraction. The trap is doing 5² − 4 as (5 − 4)² = 1." },
  { id: "t19m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "3/4", "1/8"], correct: 0, explanation: "Goal: write the fraction in simplest form. 8/12 reduces by dividing top and bottom by 4 to get 2/3. Check: 2/3 of 12 is 8. The trap is leaving the fraction unsimplified as 8/12." },
  { id: "t19m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 14, what is the value of x?", type: "grid", gridAnswers: ["19"], explanation: "Goal: solve for x. Add 5 to both sides: x = 14 + 5 = 19. Check: 19 − 5 = 14. The trap is subtracting 5 instead of adding it." },
  { id: "t19m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 24?", type: "mcq", choices: ["18", "24", "16", "54"], correct: 0, explanation: "Goal: find the mean. Add the values: 12 + 18 + 24 = 54, then divide by 3 to get 18. Check: 18 sits exactly between 12 and 24 with 18 in the middle. The trap is forgetting to divide the sum by 3." },
  { id: "t19m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 6. What is its perimeter?", type: "grid", gridAnswers: ["24"], explanation: "Goal: find the perimeter. A square has four equal sides, so P = 4 × 6 = 24. Check: 6 + 6 + 6 + 6 = 24. The trap is squaring the side to get the area, 36, instead." },
  { id: "t19m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 15, what is the value of x?", type: "mcq", choices: ["6", "9", "7", "5"], correct: 0, explanation: "Goal: solve for x. Subtract 3 to get 2x = 12, then divide by 2 to get x = 6. Check: 2(6) + 3 = 12 + 3 = 15. The trap is dividing 15 by 2 before subtracting the 3." },
  { id: "t19m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "grid", gridAnswers: ["14"], explanation: "Goal: evaluate the function. Substitute x = 6: f(6) = 6 + 8 = 14. Check: replacing x with 6 directly gives 14. The trap is multiplying instead of adding." },
  { id: "t19m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$13", "$18", "$15"], correct: 0, explanation: "Goal: scale the unit price. Each notebook costs 10 ÷ 5 = $2, so 8 cost 8 × 2 = $16. Check: $16 ÷ 8 is $2 each, matching the rate. The trap is adding $3 to $10 because there are 3 more notebooks." },
  { id: "t19m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "7", "6", "42"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 6: x = 48 ÷ 6 = 8. Check: 6 × 8 = 48. The trap is subtracting 6 from 48 instead of dividing." },
  { id: "t19m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 8 and a height of 5. What is its area?", type: "grid", gridAnswers: ["20"], explanation: "Goal: find the area of a triangle. Use A = (1/2)(base)(height) = (1/2)(8)(5) = 20. Check: half of 40 is 20. The trap is forgetting the factor of one-half and getting 40." },
  { id: "t19m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 60?", type: "mcq", choices: ["15", "25", "20", "30"], correct: 0, explanation: "Goal: find a percentage. 25% is one quarter, so 60 ÷ 4 = 15. Check: 15 × 4 = 60. The trap is taking half (30) instead of a quarter." },
  { id: "t19m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: solve for x. Multiply both sides by 3: x = 7 × 3 = 21. Check: 21 ÷ 3 = 7. The trap is dividing by 3 instead of multiplying." },
  { id: "t19m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "6", "12"], correct: 0, explanation: "Goal: evaluate the power. 3³ means 3 × 3 × 3 = 27. Check: 3 × 3 = 9 and 9 × 3 = 27. The trap is multiplying 3 by 3 to get 9 or 3 by the exponent to get 9." },
  { id: "t19m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 120 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["40", "60", "360", "30"], correct: 0, explanation: "Goal: find average speed. Divide distance by time: 120 ÷ 3 = 40 mph. Check: 40 mph for 3 hours covers 120 miles. The trap is multiplying 120 by 3 instead of dividing." },
  { id: "t19m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 8, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x. Add 8 to get 4x = 16, then divide by 4 to get x = 4. Check: 4(4) − 8 = 16 − 8 = 8. The trap is dividing 8 by 4 before adding the 8 back." },
  { id: "t19m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 18. What is its radius?", type: "mcq", choices: ["9", "18", "36", "27"], correct: 0, explanation: "Goal: find the radius. The radius is half the diameter, so 18 ÷ 2 = 9. Check: doubling 9 gives the diameter of 18. The trap is doubling the diameter instead of halving it." },
  { id: "t19m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "5", "3"], correct: 0, explanation: "Goal: evaluate y. Substitute x = 5: y = 3 × 5 = 15. Check: 15 ÷ 3 = 5, recovering x. The trap is adding 3 and 5 to get 8 instead of multiplying." },
  { id: "t19m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A jar holds 9 green and 6 yellow marbles. What fraction of the marbles are yellow?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: write the fraction of yellow marbles. There are 6 yellow out of 9 + 6 = 15 total, and 6/15 reduces to 2/5. Check: 2/5 of 15 is 6. The trap is writing 6/9 by comparing yellow only to green." },
];

