const T19_M_M2H: SatQuestion[] = [
  { id: "t19m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64 to get x² = 64, so x = ±8, and the condition x > 0 selects x = 8. Check: 8² − 64 = 64 − 64 = 0. The trap is taking the negative root or dividing 64 by 2." },
  { id: "t19m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 22 and x − 3y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve the system for x. Adding the two equations eliminates y: (4x + 3y) + (x − 3y) = 22 + 3 gives 5x = 25, so x = 5. Check: with x = 5, the second equation gives 5 − 3y = 3, so y = 2/3, and 4(5) + 3(2/3) = 20 + 2 = 22. The trap is subtracting the equations instead of adding." },
  { id: "t19m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve the exponential. Write 64 as a power of 2: 64 = 2⁶, so x = 6. Check: 2⁶ = 64. The trap is dividing 64 by 2 to get 32 instead of finding the exponent." },
  { id: "t19m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $90 is marked up by 30%. What is the new price?", type: "mcq", choices: ["$117", "$120", "$110", "$63"], correct: 0, explanation: "Goal: apply a markup. 30% of 90 is 0.30 × 90 = 27, and 90 + 27 = $117. Equivalently, 1.30 × 90 = 117. Check: $117 is 30% above $90. The trap is subtracting the markup instead of adding it." },
  { id: "t19m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find the hypotenuse. By the Pythagorean theorem, c = √(8² + 15²) = √(64 + 225) = √289 = 17. Check: 8-15-17 is a known right-triangle triple. The trap is adding the legs (23) instead of using their squares." },
  { id: "t19m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(4))?", type: "mcq", choices: ["28", "10", "34", "22"], correct: 0, explanation: "Goal: compose the function. First p(4) = 3(4) − 2 = 10, then p(10) = 3(10) − 2 = 28. Check: substituting twice in order gives 28. The trap is computing p(4) and stopping at 10 instead of applying p again." },
  { id: "t19m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 5y = 19 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["17/7", "2.428", "2.43"], explanation: "Goal: solve the system for y. Substitute x = y + 1: 2(y + 1) + 5y = 19 gives 7y + 2 = 19, so 7y = 17 and y = 17/7 ≈ 2.43. Check: x = 17/7 + 1 = 24/7, and 2(24/7) + 5(17/7) = 48/7 + 85/7 = 133/7 = 19. The trap is dropping the parentheses and forgetting to distribute the 2." },
  { id: "t19m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 12 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) = −(−8)/(2·1) = 8/2 = 4. Check: the axis of symmetry x = 4 lies midway between the roots 2 and 6. The trap is forgetting the negative sign and getting −4." },
  { id: "t19m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "15/8"], correct: 0, explanation: "Goal: find sin θ from cos θ. With adjacent 8 and hypotenuse 17, the opposite side is √(17² − 8²) = √(289 − 64) = √225 = 15, so sin θ = 15/17. Check: (8/17)² + (15/17)² = (64 + 225)/289 = 1. The trap is using 8/15 instead of the opposite over the hypotenuse." },
  { id: "t19m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find b. A perfect square (x + a)² = x² + 2ax + a² needs a² = 25, so a = 5 and b = 2a = 10. Check: (x + 5)² = x² + 10x + 25. The trap is setting b equal to 5 (the value of a) rather than 2a." },
  { id: "t19m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "8"], correct: 0, explanation: "Goal: find the y-intercept b. Using y = −3x + b with the point (2, 5): 5 = −3(2) + b, so 5 = −6 + b and b = 11. Check: the line y = −3x + 11 passes through (2, 5). The trap is sign error, adding −6 incorrectly to get −1." },
  { id: "t19m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $360. What was the original price?", type: "mcq", choices: ["$480", "$450", "$420", "$385"], correct: 0, explanation: "Goal: reverse a discount. Paying 75% of the original gives 0.75 × original = 360, so original = 360 ÷ 0.75 = $480. Check: 25% of 480 is 120, and 480 − 120 = 360. The trap is adding 25% of 360 back, which uses the wrong base." },
  { id: "t19m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: find the negative root. Since a² = 49, a = ±7, and the condition a < 0 selects a = −7. Check: (−7)² = 49. The trap is reporting the positive root 7 and ignoring the a < 0 condition." },
  { id: "t19m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the volume. Use V = πr²h = π(4²)(6) = π(16)(6) = 96π. Check: 16 × 6 = 96. The trap is using r instead of r², which would give 24π." },
  { id: "t19m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["4/3", "1.333", "1.33"], explanation: "Goal: solve for x. Subtract 1/4: 1/x = 1 − 1/4 = 3/4, so x = 4/3 ≈ 1.33. Check: 1/(4/3) + 1/4 = 3/4 + 1/4 = 1. The trap is taking the reciprocal incorrectly and writing 3/4 as the answer." },
  { id: "t19m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the roots. Factoring gives (x − 2)(x − 5) = 0, so the roots are 2 and 5 and their product is 10. As a check, the product equals c/a = 10/1 = 10. The trap is using the sum (7) instead of the product." },
  { id: "t19m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of pencils to pens in a box is 2:7. If there are 45 items total, how many are pens?", type: "mcq", choices: ["35", "30", "14", "28"], correct: 0, explanation: "Goal: split a total by a ratio. The parts total 2 + 7 = 9, so each part is 45 ÷ 9 = 5, and pens are 7 × 5 = 35. Check: pencils are 2 × 5 = 10, and 10 + 35 = 45. The trap is taking 7/9 of 45 incorrectly or using the pencil count." },
  { id: "t19m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 5, what is the area of the larger?", type: "grid", gridAnswers: ["80"], explanation: "Goal: scale the area. Areas of similar figures scale by the square of the linear ratio, so the larger area is 5 × 4² = 5 × 16 = 80. Check: the area ratio is 1:16, and 5 × 16 = 80. The trap is multiplying by 4 instead of 4²." },
  { id: "t19m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve the radical equation. Square both sides: x + 5 = 36, so x = 31. Check: √(31 + 5) = √36 = 6. The trap is forgetting to square the 6, leaving x + 5 = 6." },
  { id: "t19m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 24 and y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "7"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3: 5x − 6 = 24, add 6 to get 5x = 30, then x = 6. Check: 5(6) − 2(3) = 30 − 6 = 24. The trap is subtracting 6 from 24 instead of adding it back." },
  { id: "t19m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the root. The expression factors as (x − 3)², which equals 0 only when x = 3. Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0. The trap is expecting two distinct roots when this perfect square has just one." },
  { id: "t19m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria triples every hour. If it starts at 20, how many are there after 3 hours?", type: "mcq", choices: ["540", "180", "60", "120"], correct: 0, explanation: "Goal: apply exponential growth. After 3 hours the count is 20 × 3³ = 20 × 27 = 540. Check: 20 → 60 → 180 → 540 over three triplings. The trap is multiplying by 3 only once (60) instead of cubing the factor." },
];

